  const colorOkabeBlue = "#0072B2"; 
  const colorDotStroke = "white";
  const colorGridLine = "#f1f3f5"; // Very subtle gray
  const colorAxisText = "#6c757d";
  const colorConnectLine = "#ced4da"; // Softer gray for dumbbells
  const colorMeanLine = "#495057"; // Dark gray, not harsh black

