      return {
        id: d.id,
        trueVal: trueVal,
        y1: trueVal + (d.z_err1 * sw),
        y2: trueVal + (d.z_err2 * sw),
        mean: (trueVal + (d.z_err1 * sw) + trueVal + (d.z_err2 * sw)) / 2
