    svgA.append("g").attr("transform", `translate(0,${heightA - margin.bottom})`)
        .call(d3.axisBottom(xA).ticks(6).tickSize(-heightA + margin.top + margin.bottom).tickFormat("")).attr("color", colorGridLine).lower();

    // Axes A
    svgA.append("g").attr("transform", `translate(${margin.left},0)`).call(d3.axisLeft(yA).ticks(5)).attr("color", colorAxisText);
    svgA.append("g").attr("transform", `translate(0,${heightA - margin.bottom})`).call(d3.axisBottom(xA).ticks(0)).attr("color", colorAxisText);

    // Labels A
    svgA.append("text").attr("transform", "rotate(-90)").attr("x", -heightA/2).attr("y", 12).attr("text-anchor", "middle").attr("class", "axis-label").text("Measurement value");
    svgA.append("text").attr("x", widthA/2).attr("y", heightA - 5).attr("text-anchor", "middle").attr("class", "axis-label").text("Subjects (ranked by mean)");

    // Data A (Refined aesthetics)
    svgA.selectAll("line.connect").data(data).join("line")
      .attr("x1", (d, i) => xA(i)).attr("x2", (d, i) => xA(i))
      .attr("y1", d => yA(d.y1)).attr("y2", d => yA(d.y2))
      .attr("stroke", colorConnectLine).attr("stroke-width", 0.8); // Thinner, softer gray

    svgA.selectAll("line.mean").data(data).join("line")
      .attr("x1", (d, i) => xA(i) - 4).attr("x2", (d, i) => xA(i) + 4) 
      .attr("y1", d => yA(d.mean)).attr("y2", d => yA(d.mean))
      .attr("stroke", colorMeanLine).attr("stroke-width", 1.5); // Thinner, not pure black

    // Dots with white border for unification
    svgA.selectAll("circle.p1").data(data).join("circle")
      .attr("cx", (d, i) => xA(i)).attr("cy", d => yA(d.y1))
      .attr("r", 4).attr("fill", colorOkabeBlue).attr("stroke", colorDotStroke).attr("stroke-width", 1).attr("opacity", 0.9);

    svgA.selectAll("circle.p2").data(data).join("circle")
      .attr("cx", (d, i) => xA(i)).attr("cy", d => yA(d.y2))
      .attr("r", 4).attr("fill", colorOkabeBlue).attr("stroke", colorDotStroke).attr("stroke-width", 1).attr("opacity", 0.9);

    // --- Draw Plot B (Scatter) ---
    const widthB = cardB.node().getBoundingClientRect().width || 400;
    const heightB = 320;
    svgB.attr("viewBox", `0 0 ${widthB} ${heightB}`);
    svgB.selectAll("*").remove();

    const scaleB = d3.scaleLinear()
        .domain([-maxVal, maxVal])
        .range([margin.left, widthB - margin.right]);

    const scaleBy = d3.scaleLinear()
        .domain([-maxVal, maxVal])
        .range([heightB - margin.bottom, margin.top]);

    // Gridlines B (Subtler)
    svgB.append("g").attr("transform", `translate(0,${heightB - margin.bottom})`)
        .call(d3.axisBottom(scaleB).ticks(5).tickSize(-heightB + margin.top + margin.bottom).tickFormat("")).attr("color", colorGridLine).lower();
    svgB.append("g").attr("transform", `translate(${margin.left},0)`)
        .call(d3.axisLeft(scaleBy).ticks(5).tickSize(-widthB + margin.left + margin.right).tickFormat("")).attr("color", colorGridLine).lower();

    // Axes B
    svgB.append("g").attr("transform", `translate(0,${heightB - margin.bottom})`).call(d3.axisBottom(scaleB).ticks(5)).attr("color", colorAxisText);
    svgB.append("g").attr("transform", `translate(${margin.left},0)`).call(d3.axisLeft(scaleBy).ticks(5)).attr("color", colorAxisText);

    // Identity Line
    svgB.append("line")
      .attr("x1", scaleB(-maxVal)).attr("y1", scaleBy(-maxVal))
      .attr("x2", scaleB(maxVal)).attr("y2", scaleBy(maxVal))
      .attr("stroke", "#dc3545").attr("stroke-dasharray", "4").attr("stroke-opacity", 0.5);

